    const aNotB = a.subtract(b);
    const aNotC = a.subtract(c);
    const aNotD = a.subtract(d);

    expect(aNotB.size).toBe(21);
    expect(aNotC.size).toBe(22);
    expect(aNotD.size).toBe(23);
  });

